const FARM_ICONS={"poultry": "<path d=\"M8 15c-3 0-5-2-5-5 3 0 5 1 6 3M8 15c0 4 3 6 6 6s6-3 6-6v-4l-3-2-2 2-2-2c-1 2-1 4-1 4z\"/><path d=\"m20 11 3 2-3 1M15 9V6l2-2 1 3 2-1v5M11 21v3m5-3v3\"/><circle cx=\"17\" cy=\"12\" r=\".6\" fill=\"currentColor\"/>", "piggery": "<path d=\"M6 10c2-3 10-4 13 0l3-2v6l2 1v5h-4l-1 4h-3v-3H9v3H6v-5c-3-3-3-7 0-9zM6 12C1 9 1 15 4 15\"/><path d=\"m14 8 1-4 4 5\"/><circle cx=\"19\" cy=\"14\" r=\".7\" fill=\"currentColor\"/><path d=\"M21 17h1\"/>", "fishery": "<path d=\"M4 14c4-7 12-7 17 0-5 7-13 7-17 0zM21 14l5-5v10zM11 8l3-4 4 5M12 20l3 3 3-4\"/><circle cx=\"9\" cy=\"13\" r=\"1\" fill=\"currentColor\"/><path d=\"M14 9c-2 3-2 7 0 10\"/>", "eggs": "<path d=\"M14 3C10 3 5 13 5 18a9 9 0 0 0 18 0C23 13 18 3 14 3z\"/><path d=\"M9 18c0 3 1 4 3 5\"/>", "hatchery": "<path d=\"m5 16 4 3 4-3 4 3 6-3v3a9 9 0 0 1-18 0z\"/><path d=\"M8 16v-5a6 6 0 0 1 12 0v6M11 5l2-3 2 3m5 7 4 2-4 1\"/><circle cx=\"17\" cy=\"10\" r=\".7\" fill=\"currentColor\"/>", "cattle": "<path d=\"M7 9C3 8 2 5 3 3l5 3m13 3c4-1 5-4 4-6l-5 3M9 7h10l3 5-2 9c-2 4-10 4-12 0l-2-9zM8 10l-5 1 3 4m15-5 5 1-3 4\"/><rect x=\"9\" y=\"18\" width=\"10\" height=\"6\" rx=\"3\"/><path d=\"M12 21h0m4 0h0M10 13h1m6 0h1\"/>", "feedmill": "<path d=\"M5 12h18v13H5zM4 12l10-9 10 9M11 25v-7h6v7M14 3v8\"/><path d=\"M7 15h2m10 0h2M14 5l-9-2m9 2 9-2M14 5l-2 6m2-6 2 6\"/>", "dashboard": "<rect x=\"3\" y=\"3\" width=\"9\" height=\"9\" rx=\"2\"/><rect x=\"16\" y=\"3\" width=\"9\" height=\"9\" rx=\"2\"/><rect x=\"3\" y=\"16\" width=\"9\" height=\"9\" rx=\"2\"/><rect x=\"16\" y=\"16\" width=\"9\" height=\"9\" rx=\"2\"/>", "production": "<path d=\"M5 25V10h18v15M3 10l11-7 11 7M8 14h4v4H8m8-4h4v4h-4M12 25v-4h4v4\"/>", "inventory": "<path d=\"m3 8 11-5 11 5-11 5zM3 8v13l11 5 11-5V8M14 13v13M8 6l11 5\"/>", "sales": "<path d=\"M3 21 11 13l5 4 9-12M18 5h7v7\"/><path d=\"M4 26h21\"/>", "expenses": "<path d=\"M6 3h16v23l-4-2-4 2-4-2-4 2zM10 8h8M10 13h8M10 18h4\"/>", "reports": "<path d=\"M4 3v22h21M9 20v-6m6 6V7m6 13v-9\"/>", "users": "<circle cx=\"11\" cy=\"8\" r=\"4\"/><path d=\"M3 25v-4a8 8 0 0 1 16 0v4M20 4a4 4 0 0 1 0 8m2 5a7 7 0 0 1 4 7\"/>", "audit": "<circle cx=\"14\" cy=\"14\" r=\"11\"/><path d=\"M14 7v7l5 3\"/>", "check": "<path d=\"m5 15 6 6L24 7\"/>", "alert": "<path d=\"m14 3 12 22H2zM14 10v7m0 4h0\"/>", "money": "<rect x=\"2\" y=\"6\" width=\"24\" height=\"16\" rx=\"3\"/><circle cx=\"14\" cy=\"14\" r=\"4\"/><path d=\"M6 14h0m16 0h0\"/>"};
function farmIcon(name){return `<svg viewBox="0 0 28 28" class="farm-icon" aria-hidden="true" fill="none" stroke="currentColor" stroke-width="1.65" stroke-linecap="round" stroke-linejoin="round">${FARM_ICONS[name]||FARM_ICONS.production}</svg>`}
function divisionArt(name){return `<svg class="division-art" viewBox="0 0 220 90" aria-hidden="true"><circle cx="180" cy="23" r="16" fill="currentColor" opacity=".15"/><path d="M0 76Q50 35 120 73T220 62V90H0Z" fill="currentColor" opacity=".07"/><path d="M0 85Q85 60 140 79T220 70V90H0Z" fill="currentColor" opacity=".12"/><g transform="translate(85 9) scale(2.25)" fill="none" stroke="currentColor" stroke-width="1.25" stroke-linecap="round" stroke-linejoin="round">${FARM_ICONS[name]}</g><path d="M24 68V44m0 11-7-5m7 12 8-6M204 71V48m0 10-6-6" fill="none" stroke="currentColor" opacity=".3" stroke-width="2"/></svg>`}
const DIVS=[['poultry','Poultry','♧','Flock and bird sales'],['piggery','Piggery','♧','Pig groups and growth'],['fishery','Fishery','≋','Ponds and harvests'],['eggs','Egg production','◉','Collection and saleable stock'],['hatchery','Hatchery','✳','Incubation and hatch rates'],['cattle','Cattle','♉','Animals and weights'],['feedmill','Feedmill','◍','Ingredients and feed output']];
const ROLE={admin:'Administrator',manager:'Farm manager',storekeeper:'Storekeeper',sales_officer:'Sales officer',division_staff:'Division staff'};
const $=s=>document.querySelector(s); const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c])); const num=n=>Number(n||0); const money=n=>'₦'+new Intl.NumberFormat('en-NG',{maximumFractionDigits:2}).format(num(n)); const fmt=n=>new Intl.NumberFormat('en-NG',{maximumFractionDigits:2}).format(num(n)); const day=d=>d?new Date(d+'T12:00:00').toLocaleDateString('en-NG',{day:'numeric',month:'short',year:'numeric'}):'—'; const today=()=>new Date().toISOString().slice(0,10);
let state=null, user=null, page=routePage(), toastTimer;
async function api(action,payload={}){const r=await fetch('/api/action',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({action,payload})});const j=await r.json().catch(()=>({}));if(!r.ok)throw Error(j.error||'Something went wrong.');return j.data}
function toast(s,error=false){const t=$('#toast');t.textContent=s;t.className='toast show'+(error?' error':'');clearTimeout(toastTimer);toastTimer=setTimeout(()=>t.className='toast',3200)}
function openApp(data){const arriving=!state;state=data;user=data.user;$('#login').classList.add('hidden');$('#app').classList.remove('hidden');$('#profile-name').textContent=user.name.replace(/ \(Demo\)/g,'');$('#profile-role').textContent=ROLE[user.role]||user.role;$('#avatar').textContent=$('#top-avatar').textContent=(user.name||'A').slice(0,1).toUpperCase();$('#today').textContent=new Intl.DateTimeFormat('en-US',{weekday:'short',month:'short',day:'numeric'}).format(new Date());buildNav();render();routeTitle();if(arriving)announcePage()}
async function refresh(){const s=await api('state');openApp(s)}
$('#login-form').addEventListener('submit',async e=>{e.preventDefault();$('#login-error').textContent='';const fd=new FormData(e.target);const b=e.target.querySelector('button');b.disabled=true;b.innerHTML='Signing in…';try{const data=await api('login',{email:fd.get('email'),password:fd.get('password')});await refresh();}catch(err){$('#login-error').textContent=err.message;b.innerHTML='Sign in <span>→</span>'}finally{b.disabled=false;b.innerHTML='Sign in <span>→</span>'}});
$('#logout').addEventListener('click',async()=>{try{await api('logout')}catch{}state=null;user=null;$('#app').classList.add('hidden');$('#login').classList.remove('hidden');$('#login-form').reset();$('#login-error').textContent=''});
$('#menu-toggle').addEventListener('click',()=>{$('#sidebar').classList.add('open');$('#scrim').classList.add('open')});$('#scrim').addEventListener('click',()=>{$('#sidebar').classList.remove('open');$('#scrim').classList.remove('open')});
function buildNav(){let items=[['dashboard','Overview','⌂',''],['production','Production records','▦',''],['inventory','Inventory','▤',''],['sales','Sales & payments','↗',''],['expenses','Expenses','−',''],['reports','Reports & exports','▥','']];let html=items.map(([id,label,icon])=>`<a href="/${id}" class="nav-link ${page===id?'active':''}" data-page="${id}"><span class="nav-icon">${farmIcon(id)}</span>${label}</a>`).join('')+'<div class="nav-group">FARM DIVISIONS</div>'+DIVS.filter(d=>user.role!=='division_staff'||user.division===d[0]).map(([id,name,icon])=>`<a href="/${id}" class="nav-link ${page===id?'active':''}" data-page="${id}"><span class="nav-icon">${farmIcon(id)}</span>${name}</a>`).join('');if(user.role==='admin')html+='<div class="nav-group">ADMINISTRATION</div><a href="/users" class="nav-link '+(page==='users'?'active':'')+'" data-page="users"><span class="nav-icon">'+farmIcon('users')+'</span>Staff accounts</a><a href="/audit" class="nav-link '+(page==='audit'?'active':'')+'" data-page="audit"><span class="nav-icon">'+farmIcon('audit')+'</span>Audit history</a>';$('#nav').innerHTML=html;$('#nav').querySelectorAll('[data-page]').forEach(a=>a.addEventListener('click',e=>{if(e.ctrlKey||e.metaKey||e.shiftKey||e.altKey)return;e.preventDefault();go(a.dataset.page)}))}
function routePage(){const p=location.pathname.split('/').filter(Boolean)[0]||'dashboard';return ['dashboard','production','inventory','sales','expenses','reports','users','audit',...DIVS.map(d=>d[0])].includes(p)?p:'dashboard'}
function routeTitle(){const label=DIVS.find(d=>d[0]===page)?.[1]||({dashboard:'Overview',production:'Production records',inventory:'Inventory',sales:'Sales & payments',expenses:'Expenses',reports:'Reports & exports',users:'Staff accounts',audit:'Audit history'}[page]||'Overview');document.title=label+' | Fol-Hope Farm';return label}
let pageArrivalTimer;
function announcePage(){let notice=document.getElementById('page-arrival');if(!notice){notice=document.createElement('div');notice.id='page-arrival';notice.className='page-arrival';notice.setAttribute('role','status');notice.setAttribute('aria-live','polite');document.body.appendChild(notice)}clearTimeout(pageArrivalTimer);notice.textContent=routeTitle();notice.textContent=notice.textContent.replace(' | Fol-Hope Farm','');notice.classList.remove('visible');void notice.offsetWidth;notice.classList.add('visible');const content=$('#content');content.classList.remove('page-enter');void content.offsetWidth;content.classList.add('page-enter');pageArrivalTimer=setTimeout(()=>notice.classList.remove('visible'),1700)}
function go(p,fromHistory=false){const valid=['dashboard','production','inventory','sales','expenses','reports','users','audit',...DIVS.map(d=>d[0])];if(!valid.includes(p))p='dashboard';page=p;const path='/'+p;if(!fromHistory&&location.pathname!==path)history.pushState({page:p},'',path);buildNav();$('#sidebar').classList.remove('open');$('#scrim').classList.remove('open');closeModal();render();routeTitle();window.scrollTo({top:0,left:0,behavior:'instant'});const h=$('#content h1');if(h){h.setAttribute('tabindex','-1');h.focus({preventScroll:true})}announcePage()}
if('scrollRestoration' in history)history.scrollRestoration='manual';
window.addEventListener('popstate',()=>{page=routePage();if(state)go(page,true)});
function heading(eyebrow,title,description,actions=''){return `<div class="page-heading"><div><span class="eyebrow">${eyebrow}</span><h1>${title}</h1><p>${description}</p></div><div class="heading-actions">${actions}</div></div>`}
const btn=(text,fn='new',secondary=false)=>`<button class="btn ${secondary?'btn-ghost':'btn-primary'}" data-action="${fn}">${secondary?'+ ':''}${text}${secondary?'':' <span>＋</span>'}</button>`;
function panel(title,sub,body,right=''){return `<section class="panel"><div class="panel-heading"><div><h3>${title}</h3>${sub?`<p>${sub}</p>`:''}</div>${right}</div>${body}</section>`}
function listTable(headers,rows,empty='No records yet. Add the first one to begin.') {return `<div class="table-wrap"><table><thead><tr>${headers.map(h=>`<th>${h}</th>`).join('')}</tr></thead><tbody>${rows||''}</tbody></table>${rows?`<div class="table-foot">${(rows.match(/<tr/g)||[]).length} record${(rows.match(/<tr/g)||[]).length===1?'':'s'} · Records saved to your farm workspace</div>`:`<div class="empty">${empty}</div>`}</div>`}
function kpi(label,value,foot,icon){return `<div class="kpi"><div class="kpi-top"><span class="kpi-label">${label}</span><span class="kpi-icon">${farmIcon(({"↗":"sales","✓":"check","−":"expenses","◷":"audit","₦":"money","!":"alert","▤":"inventory","▦":"production"})[icon]||"production")}</span></div><div class="kpi-value">${value}</div><div class="kpi-foot">${foot}</div></div>`}
function render(){if(!state)return;const map={dashboard:dashboard,production:production,inventory:inventory,sales:sales,expenses:expenses,reports:reports,users:usersPage,audit:auditPage};const d=DIVS.find(x=>x[0]===page);const html=d?divisionPage(d): (map[page]||dashboard)();$('#content').innerHTML=html;$('#crumb-current').textContent=(DIVS.find(x=>x[0]===page)?.[1])||({dashboard:'Overview',production:'Production records',inventory:'Inventory',sales:'Sales & payments',expenses:'Expenses',reports:'Reports & exports',users:'Staff accounts',audit:'Audit history'}[page]||'Overview');bindPage();if(page==='reports')loadReport()}
function production(){const rows=(state.batches||[]).map(b=>`<tr><td>${esc(b.code)}</td><td>${esc(b.division_slug)}</td><td>${esc(b.subtype)}</td><td>${day(b.start_date)}</td><td>${fmt(b.balance)} ${esc(b.quantity_unit)}</td><td>${status(b.status)}</td><td><button class="row-action" data-event="${b.id}">+ Movement</button></td></tr>`).join('');return heading('PRODUCTION','Production records','Saved production batches across farm divisions.',btn('Add batch'))+panel('Batch register','Balances use posted stock movements.',listTable(['Batch','Division','Type','Opened','Balance','Status','Actions'],rows))+`<div class="section-gap">${panel('Movement history','Dated changes to batch quantities.',eventsTable(state.events||[]))}</div>`}
function dashboard(){
 const sales=(state.sales||[]).filter(s=>s.status==='posted'),expenses=(state.expenses||[]).filter(e=>e.status==='posted'),items=state.items||[],low=items.filter(i=>num(i.balance)<=num(i.reorder_level)&&num(i.reorder_level)>0),month=today().slice(0,7),monthly=sales.filter(s=>s.sale_date.slice(0,7)===month),revenue=monthly.reduce((a,s)=>a+num(s.total_amount),0),paid=monthly.reduce((a,s)=>a+num(s.paid_amount),0),spend=expenses.filter(e=>e.expense_date.slice(0,7)===month).reduce((a,e)=>a+num(e.amount),0),due=sales.reduce((a,s)=>a+num(s.total_amount)-num(s.paid_amount),0);
 const buckets=Array.from({length:7},(_,n)=>{const d=new Date(Date.now()-(6-n)*864e5).toISOString().slice(0,10);return {d,s:sales.filter(x=>x.sale_date===d).reduce((a,x)=>a+num(x.total_amount),0),e:expenses.filter(x=>x.expense_date===d).reduce((a,x)=>a+num(x.amount),0)}}),max=Math.max(1,...buckets.flatMap(x=>[x.s,x.e]));
 const chart=buckets.map(x=>`<div class="chart-column"><div class="chart-bars"><div class="chart-bar revenue" style="height:${Math.max(2,x.s/max*100)}%" title="Sales ${money(x.s)}"><span>${money(x.s)}</span></div><div class="chart-bar cost" style="height:${Math.max(2,x.e/max*100)}%" title="Expenses ${money(x.e)}"></div></div><span>${new Date(x.d+'T12:00:00').toLocaleDateString('en',{weekday:'short'})}</span></div>`).join('');
 const cards=DIVS.filter(d=>user.role!=='division_staff'||user.division===d[0]).map(([id,name,ico,desc])=>{const batches=(state.batches||[]).filter(x=>x.division_slug===id);let value=batches.reduce((a,b)=>a+num(b.balance),0),label={poultry:'birds on hand',piggery:'pigs on farm',fishery:'fish in ponds',eggs:'saleable eggs',hatchery:'hatch success',cattle:'active cattle',feedmill:'kg of finished feed'}[id];if(id==='eggs')value=num(items.find(x=>x.sku==='EGGS-GOOD')?.balance);if(id==='cattle')value=(state.animals||[]).filter(x=>x.status==='active').length;if(id==='feedmill')value=items.filter(x=>x.item_type==='finished_feed').reduce((a,x)=>a+num(x.balance),0);if(id==='hatchery'){const set=(state.hatchery||[]).reduce((a,x)=>a+num(x.eggs_set),0);value=set?(state.hatchery||[]).reduce((a,x)=>a+num(x.chicks_hatched),0)/set*100:0;}return `<button class="operation-card operation-${id}" data-page="${id}">${divisionArt(id)}<div class="operation-top"><span class="operation-icon">${farmIcon(id)}</span><span class="operation-arrow">↗</span></div><h3>${name}</h3><strong>${id==='hatchery'?value.toFixed(1)+'%':fmt(value)}</strong><span class="operation-label">${label}</span><div class="operation-foot">${desc}<span>View records →</span></div></button>`}).join('');
 const rows=sales.slice(0,5).map(s=>`<tr><td><b>${esc(s.customer)}</b><small>${day(s.sale_date)} · ${esc(s.division_slug)}</small></td><td>${money(s.total_amount)}</td><td><span class="status ${num(s.paid_amount)>=num(s.total_amount)?'healthy':'draft'}">${num(s.paid_amount)>=num(s.total_amount)?'Paid':'Part paid'}</span></td></tr>`).join('');
 const alerts=low.slice(0,4).map(i=>`<button class="attention-item" data-page="inventory"><span class="attention-icon">!</span><span><b>${esc(i.product_name)}</b><small>${fmt(i.balance)} ${esc(i.unit)} left · reorder at ${fmt(i.reorder_level)}</small></span><span>→</span></button>`).join('');
 return `<div class="welcome-banner"><div><span class="eyebrow">FOL-HOPE FARM · OPERATIONS OVERVIEW</span><h1>Your farm, at a glance.</h1><p>See what’s moving, what’s earning and what needs your attention.</p></div><div class="welcome-actions"><button class="btn btn-primary" data-action="new-sale">Record a sale <span>＋</span></button><button class="btn btn-ghost" data-page="production">View production →</button></div></div><div class="kpis financial-kpis">${kpi('Sales this month',money(revenue),'Value of posted sales','↗')}${kpi('Payments received',money(paid),'Collected against this month’s sales','✓')}${kpi('Expenses this month',money(spend),'Recorded operating expenditure','−')}${kpi('Outstanding payments',money(due),'Balance across all unpaid sales','◷')}</div><div class="insight-grid">${panel('Sales & spending','Actual posted transactions · last 7 days',`<div class="chart-legend"><span><i></i>Sales</span><span><i class="cost"></i>Expenses</span></div><div class="weekly-chart">${chart}</div>`,'<button class="subtle-link" data-page="reports">Full report →</button>')}<section class="collection-panel"><span class="eyebrow">PAYMENT COLLECTION</span><h2>${revenue?Math.round(paid/revenue*100):0}%</h2><p>of this month’s sales collected</p><div class="collection-track"><i style="width:${revenue?Math.min(100,paid/revenue*100):0}%"></i></div><div class="collection-detail"><span>Collected<b>${money(paid)}</b></span><span>Still due<b>${money(revenue-paid)}</b></span></div><button data-page="sales">Review outstanding sales →</button></section></div><div class="section-title"><div><span class="eyebrow">SEVEN CONNECTED DIVISIONS</span><h2>What’s happening on the farm</h2></div><button class="subtle-link" data-page="production">All production →</button></div><div class="operations-grid">${cards}</div><div class="bottom-grid">${panel('Recent sales','Latest customer orders and payment status',listTable(['Customer / date','Sale value','Payment'],rows),' <button class="subtle-link" data-page="sales">All sales →</button>')}${panel('Needs your attention',low.length+' stock items at or below reorder level',alerts||'<div class="empty">Stock levels are healthy.</div>','<button class="subtle-link" data-page="inventory">Manage stock →</button>')}</div>`;
}
function divisionPage(d){const[id,name,icon,desc]=d;if(id==='cattle')return cattlePage(d);if(id==='eggs')return eggPage(d);if(id==='hatchery')return hatchPage(d);if(id==='feedmill')return feedPage(d);const bs=(state.batches||[]).filter(x=>x.division_slug===id),rows=bs.map(b=>`<tr><td>${esc(b.code)}</td><td>${esc(b.subtype||'—')}</td><td>${day(b.start_date)}</td><td>${fmt(b.initial_qty)}</td><td><b>${fmt(b.balance)}</b> ${esc(b.quantity_unit)}</td><td>${status(b.status)}</td><td><button class="row-action" data-event="${b.id}">+ Movement</button></td></tr>`).join('');const total=bs.reduce((a,b)=>a+num(b.balance),0),unit=bs[0]?.quantity_unit||'head';return heading(name.toUpperCase(),name,desc+'. Record each change once; balances are calculated from the stock ledger.',btn('Add batch'))+`<div class="kpis">${kpi('Active batches',bs.filter(x=>x.status==='active').length,'Currently tracked',icon)}${kpi(id==='fishery'?'Fish remaining':id==='piggery'?'Animals on farm':'Birds on hand',fmt(total),unit+' across active batches','◉')}${kpi('Recent movements',(state.events||[]).filter(x=>x.division_slug===id).length,'Movement history available','↗')}${kpi('Reorder alerts',state.items.filter(x=>x.division_slug===id&&num(x.balance)<=num(x.reorder_level)).length,'Supplies at threshold','!')}</div>${panel('Production batches','Opening quantity plus recorded movements. Changes are logged in the audit history.',listTable(['Batch code','Breed / type','Date opened','Opening quantity','Current balance','Status',''],rows),btn('Add batch'))}`+`<div class="section-gap">${panel('Recent movements','Posted adjustments, births, mortalities, transfers and harvests.',eventsTable((state.events||[]).filter(e=>bs.some(b=>b.id===e.batch_id))))}</div>`}
function eventsTable(ev){const rows=ev.map(e=>`<tr><td>${esc(e.batch_code)}</td><td>${esc(e.event_type.replaceAll('_',' '))}</td><td>${day(e.event_date)}</td><td>${fmt(e.quantity)} ${esc(e.unit)}</td><td>${esc(e.notes||'—')}</td></tr>`).join('');return listTable(['Batch','Movement','Date','Quantity','Notes'],rows,'Movements appear here after a batch update.')}
function cattlePage(d){const animals=state.animals||[];const rows=animals.map(a=>`<tr><td>${esc(a.tag)}</td><td>${esc(a.breed||'—')}</td><td>${esc(a.sex)}</td><td>${day(a.acquired_at)}</td><td>${a.current_weight_kg?fmt(a.current_weight_kg)+' kg':'—'}</td><td>${status(a.status)}</td><td><button class="row-action" data-weight="${a.id}">+ Weight</button></td></tr>`).join('');const count=animals.filter(x=>x.status==='active').length,weight=animals.filter(x=>x.status==='active'&&x.current_weight_kg).reduce((n,x)=>n+num(x.current_weight_kg),0);return heading('CATTLE','Cattle register','Maintain animal records and dated weight history.',btn('Register animal'))+`<div class="kpis">${kpi('Active cattle',count,'Individual animal records','♉')}${kpi('Weights recorded',animals.reduce((n,x)=>n+(x.weights||[]).length,0),'Dated, auditable measurements','↗')}${kpi('Combined current weight',fmt(weight)+' kg','Animals with a recorded weight','◉')}${kpi('Closed records',animals.length-count,'Sold or deceased animals','✓')}</div>${panel('Animal records','Open each animal’s weight history by adding a dated entry.',listTable(['Animal tag','Breed','Sex','Date entered','Latest weight','Status',''],rows),btn('Register animal'))}`}
function eggPage(){const good=state.items.find(x=>x.sku==='EGGS-GOOD')?.balance||0,collections=state.eggs||[],rows=collections.map(e=>`<tr><td>${day(e.collected_on)}</td><td>${esc(e.batch_code||'—')}</td><td>${fmt(e.good_count)}</td><td>${fmt(e.damaged_count)}</td><td>${fmt(num(e.good_count)+num(e.damaged_count))}</td><td>${esc(e.note||'—')}</td></tr>`).join('');return heading('EGG PRODUCTION','Egg collections','Record good and damaged eggs. Good eggs add to saleable inventory.',btn('Record collection'))+`<div class="kpis">${kpi('Saleable eggs',fmt(good),'Current stock from posted collections and sales','◉')}${kpi('Collections',collections.length,'Collection records','↗')}${kpi('Good eggs collected',fmt(collections.reduce((n,x)=>n+num(x.good_count),0)),'Cumulative recorded','✓')}${kpi('Damaged eggs',fmt(collections.reduce((n,x)=>n+num(x.damaged_count),0)),'Kept separate from saleable stock','!')}</div>${panel('Collection history','Collection posting increases the egg stock ledger once.',listTable(['Collected','Flock batch','Good eggs','Damaged eggs','Total','Note'],rows),btn('Record collection'))}`}
function hatchPage(){const hs=state.hatchery||[],rows=hs.map(h=>`<tr><td>${esc(h.code)}</td><td>${day(h.set_date)}</td><td>${h.hatch_date?day(h.hatch_date):'—'}</td><td>${fmt(h.eggs_set)}</td><td>${fmt(h.chicks_hatched)}</td><td>${fmt(h.rejected_eggs)}</td><td><b>${h.eggs_set?((h.chicks_hatched/h.eggs_set)*100).toFixed(1):'0.0'}%</b></td><td>${status('active')}</td></tr>`).join('');const eggs=hs.reduce((n,x)=>n+num(x.eggs_set),0),chicks=hs.reduce((n,x)=>n+num(x.chicks_hatched),0);return heading('HATCHERY','Incubation batches','Track eggs set, hatch outcomes and rejection rates.',btn('Add hatch batch'))+`<div class="kpis">${kpi('Incubation batches',hs.length,'Total recorded','✳')}${kpi('Eggs set',fmt(eggs),'Cumulative total','◉')}${kpi('Chicks hatched',fmt(chicks),'Cumulative total','✓')}${kpi('Overall hatch rate',eggs?((chicks/eggs)*100).toFixed(1)+'%':'0.0%','Chicks hatched ÷ eggs set','↗')}</div>${panel('Hatchery register','A hatch batch cannot report more hatched and rejected eggs than were set.',listTable(['Batch code','Set date','Hatch date','Eggs set','Chicks','Rejected','Hatch rate','Status'],rows),btn('Add hatch batch'))}`}
function feedPage(){const bs=state.feed_batches||[],rows=bs.map(b=>`<tr><td>${esc(b.code)}</td><td>${day(b.produced_on)}</td><td>${esc(b.output_name)}</td><td><b>${fmt(b.output_kg)} kg</b></td><td>${(b.inputs||[]).map(x=>esc(x.product_name)+' '+fmt(x.quantity_kg)+' kg').join(' · ')||'—'}</td><td>${status('posted')}</td></tr>`).join('');const inputs=state.items.filter(x=>x.item_type==='ingredient').reduce((n,x)=>n+num(x.balance),0),output=state.items.filter(x=>x.item_type==='finished_feed').reduce((n,x)=>n+num(x.balance),0);return heading('FEEDMILL','Feed production','Consume ingredient stock and post finished feed atomically.',btn('Produce feed'))+`<div class="kpis">${kpi('Ingredients on hand',fmt(inputs)+' kg','Across stocked feed inputs','◍')}${kpi('Finished feed stock',fmt(output)+' kg','Across finished-feed items','▤')}${kpi('Production batches',bs.length,'Successfully posted','↗')}${kpi('Raw ingredient types',state.items.filter(x=>x.item_type==='ingredient').length,'Tracked inventory items','✓')}</div>${panel('Production batches','Every ingredient reduction and finished-feed posting is committed together.',listTable(['Batch','Date','Feed type','Output','Ingredients used','Status'],rows),btn('Produce feed'))}`}
function status(s){return `<span class="status ${esc(s)}">${esc(String(s||'active').replaceAll('_',' '))}</span>`}
function inventory(){const items=state.items||[],groups=[['All items','all'],['Poultry','poultry'],['Feedmill inputs','ingredients'],['Finished feed','finished_feed'],['Eggs','eggs'],['Low stock','low']];const rows=items.map(i=>{const low=num(i.balance)<=num(i.reorder_level);return `<tr data-search="${esc((i.sku+' '+i.product_name+' '+i.unit+' '+i.division_slug).toLowerCase())}" data-kind="${esc(i.item_type)}" data-division="${esc(i.division_slug||'common')}" data-low="${low}"><td>${esc(i.sku)}</td><td>${esc(i.product_name)}</td><td>${esc(i.division_slug||'Shared').replaceAll('_',' ')}</td><td><div class="stock-bar"><b class="stock-short">${fmt(i.balance)} ${esc(i.unit)}</b><span class="stock-track"><i class="${low?'low':''}" style="width:${Math.min(100,num(i.reorder_level)?num(i.balance)/num(i.reorder_level)*100:100)}%"></i></span></div></td><td>${fmt(i.reorder_level)} ${esc(i.unit)}</td><td>${low?'<span class="status draft">Low stock</span>':status('healthy')}</td><td>${user.role==='admin'||user.role==='manager'||user.role==='storekeeper'?`<button class="row-action" data-stock="${i.id}">Adjust</button>`:''}</td></tr>`}).join('');return heading('INVENTORY','Stock ledger','Receipts, issues and sales update item balances. All movements are retained.',user.role==='admin'||user.role==='manager'||user.role==='storekeeper'?btn('Record movement'): '')+`<div class="kpis">${kpi('Tracked items',items.length,'Across divisions and shared stock','▤')}${kpi('Needs reorder',items.filter(i=>num(i.balance)<=num(i.reorder_level)).length,'At or below reorder level','!')}${kpi('Distinct divisions',new Set(items.map(i=>i.division_slug)).size,'Represented in inventory','▦')}${kpi('Posted movements',(state.metrics?.stock_count||0)+(state.events||[]).length,'Operational records','↗')}</div>${panel('Item balances','Each quantity has one unit of measure; the current balance is the sum of the ledger.',`<div class="toolbar"><input id="inventory-search" class="search-input" placeholder="Search products or SKU…"><select id="inventory-filter" class="filter-control">${groups.map(([n,v])=>`<option value="${v}">${n}</option>`).join('')}</select></div>`+listTable(['SKU','Product','Division','On hand','Reorder level','Signal',''],rows),'<span class="eyebrow">LIVE STOCK</span>')}`}
function sales(){const rows=(state.sales||[]).map(s=>`<tr><td>${esc(s.sale_no)}</td><td>${day(s.sale_date)}</td><td>${esc(s.customer)}</td><td>${esc(s.division_slug||'—')}</td><td>${money(s.total_amount)}</td><td>${money(s.paid_amount)}</td><td>${money(num(s.total_amount)-num(s.paid_amount))}</td><td>${status(s.status)}</td><td>${s.status==='posted'?`<button class="row-action" data-payment="${s.id}">+ Payment</button> ${user.role==='admin'||user.role==='manager'?`<button class="row-action danger" data-void-sale="${s.id}">Void</button>`:''}`:'—'}</td></tr>`).join('');const active=(state.sales||[]).filter(s=>s.status==='posted');return heading('SALES','Sales & payments','Track sales, payment collection and the balance due.',user.role!=='storekeeper'?btn('Record a sale'):'')+`<div class="kpis">${kpi('Posted sales',active.length,'Saved sale records','↗')}${kpi('Sales value',money(active.reduce((n,s)=>n+num(s.total_amount),0)),'Total posted sales','₦')}${kpi('Payments received',money(active.reduce((n,s)=>n+num(s.paid_amount),0)),'Recorded payments','✓')}${kpi('Balance due',money(active.reduce((n,s)=>n+num(s.total_amount)-num(s.paid_amount),0)),'Unpaid posted sales','◷')}</div>${panel('Sales register','A sale deducts available stock on posting. Voiding requires manager approval and creates a reversal.',listTable(['Sale #','Date','Customer','Division','Total','Paid','Balance','Status','Actions'],rows),'<span class="eyebrow">NGN · TWO DECIMAL PLACES</span>')}`}
function expenses(){const rows=(state.expenses||[]).map(e=>`<tr><td>${day(e.expense_date)}</td><td>${esc(e.category)}</td><td>${esc(e.division_slug)}</td><td>${esc(e.description)}</td><td>${money(e.amount)}</td><td>${status(e.status)}</td><td>${e.status==='posted'?`${user.role==='admin'||user.role==='manager'?`<button class="row-action" data-edit-expense="${e.id}">Edit</button> <button class="row-action" data-void-expense="${e.id}">Void</button>`:'—'}`:'—'}</td></tr>`).join('');const active=(state.expenses||[]).filter(e=>e.status==='posted'),month=active.filter(e=>e.expense_date?.slice(0,7)===today().slice(0,7)).reduce((n,e)=>n+num(e.amount),0);return heading('EXPENSES','Expense register','Record operational spending by division. Voided transactions stay in the audit trail.',user.role==='admin'||user.role==='manager'?btn('Record an expense'):'')+`<div class="kpis">${kpi('Posted expenses',active.length,'Records not voided','−')}${kpi('This month',money(month),'Current calendar month','₦')}${kpi('All posted',money(active.reduce((n,e)=>n+num(e.amount),0)),'Total recorded expenditure','↗')}${kpi('Expense categories',new Set(active.map(e=>e.category)).size,'Distinct categories','▦')}</div>${panel('Expenses','Amounts must be positive and use NGN.',listTable(['Date','Category','Division','Description','Amount','Status','Actions'],rows),'<span class="eyebrow">NGN</span>')}`}
function reports(){return `<div id="report-wrap">${heading('REPORTING','Reports & exports','Filter saved transactions by date and division. Export CSV or print a clean report.')}<div class="panel"><div class="report-filters"><label class="field">From<input id="report-from" type="date" value="${new Date(Date.now()-29*864e5).toISOString().slice(0,10)}"></label><label class="field">To<input id="report-to" type="date" value="${today()}"></label><label class="field">Division<select id="report-division"><option value="all">All divisions</option>${(state.divisions||[]).map(d=>`<option value="${esc(d.slug)}">${esc(d.name)}</option>`).join('')}</select></label><button class="btn btn-primary" id="run-report">Apply filters <span>→</span></button><button class="btn btn-ghost" id="csv-export">Export CSV ↓</button><button class="btn btn-ghost" id="print-report">Print</button></div></div><div id="report-data"></div></div>`}
function renderReport(data,filters={}){const from=filters.from||$('#report-from')?.value,to=filters.to||$('#report-to')?.value;const days=from&&to?Math.round((Date.parse(to)-Date.parse(from))/86400000)+1:0;const duration=from&&to?`${day(from)} – ${day(to)} · ${days} day${days===1?'':'s'}`:'All dates';const division=filters.division&&filters.division!=='all'?(state.divisions||[]).find(d=>d.slug===filters.division)?.name||filters.division:'All divisions';const wrap=$('#report-data');if(!wrap)return;wrap.innerHTML=`<div class="report-cards"><div class="panel report-kpi"><span>Sales</span><small class="report-period">${esc(duration)}<br>${esc(division)}</small><b>${money(data.sales)}</b></div><div class="panel report-kpi"><span>Payments received</span><small class="report-period">${esc(duration)}<br>${esc(division)}</small><b>${money(data.paid)}</b></div><div class="panel report-kpi"><span>Expenses</span><small class="report-period">${esc(duration)}<br>${esc(division)}</small><b>${money(data.expenses)}</b></div></div><div class="dashboard-grid"><div>${panel('Posted sales','Void sales are excluded.',listTable(['Sale','Date','Division','Customer','Total','Paid'],(data.sales_rows||[]).map(s=>`<tr><td>${esc(s.sale_no)}</td><td>${day(s.sale_date)}</td><td>${esc(s.division_name||'—')}</td><td>${esc(s.customer)}</td><td>${money(s.total_amount)}</td><td>${money(s.paid_amount)}</td></tr>`).join('')))}</div><div>${panel('Posted expenses','Void expenses are excluded.',listTable(['Date','Division','Category','Amount'],(data.expense_rows||[]).map(e=>`<tr><td>${day(e.expense_date)}</td><td>${esc(e.division_name)}</td><td>${esc(e.category)}</td><td>${money(e.amount)}</td></tr>`).join('')))}</div></div>`}
function usersPage(){const rows=(state.users||[]).map(x=>`<tr><td>${esc(x.full_name.replace(/ \(Demo\)/g,''))}</td><td>${esc(x.email)}</td><td>${ROLE[x.role]||esc(x.role)}</td><td>${esc(x.division_slug||'All divisions')}</td><td>${status(x.active?'active':'closed')}</td><td>${x.id!==user.id?`<button class="row-action" data-edit-user="${x.id}">Edit</button>`:'You'}</td></tr>`).join('');return heading('TEAM ACCESS','Staff accounts','Administrator controls for secure role and division assignments.',btn('Add a staff account'))+panel('Farm team','Accounts are assigned the minimum role needed for their duties.',listTable(['Name','Email','Role','Assignment','Access',''],rows))}
function auditPage(){const logs=state.audit||[],edited=logs.filter(a=>a.detail?.changes);const value=v=>v===null||v===undefined?'Not set':typeof v==='boolean'?(v?'Yes':'No'):typeof v==='object'?JSON.stringify(v):String(v);const rows=logs.map(a=>{const changes=a.detail?.changes||{},keys=Object.keys(changes),ref=a.detail?.reference||a.detail?.code||a.detail?.sale_no||a.detail?.category||a.entity_id||'—';const detail=keys.length?`<details class="audit-details"><summary>${keys.length} field${keys.length===1?'':'s'} changed · View changes</summary><table class="audit-diff"><thead><tr><th>Field</th><th>Before</th><th>After</th></tr></thead><tbody>${keys.map(k=>`<tr><td>${esc(k.replaceAll('_',' '))}</td><td class="audit-before">${esc(value(changes[k].before))}</td><td class="audit-after">${esc(value(changes[k].after))}</td></tr>`).join('')}</tbody></table></details>`:`<span class="muted">${esc(Object.entries(a.detail||{}).filter(([k])=>!['before','after'].includes(k)).map(([k,v])=>k.replaceAll('_',' ')+': '+value(v)).join(' · ')||'Action recorded')}</span>`;return `<tr data-audit-search="${esc([a.actor_name,a.action,a.entity_type,ref,...keys].join(' ').toLowerCase())}"><td>${new Date(a.occurred_at).toLocaleString('en-NG')}</td><td>${esc((a.actor_name||'System / database').replace(/ \(Demo\)/g,''))}</td><td><span class="status">${a.action==='record_edited'?'Record edited':a.action==='demo_seed'?'Opening records':esc(a.action.replaceAll('_',' '))}</span></td><td>${esc(a.entity_type.replaceAll('_',' '))}<small>${esc(ref)}</small></td><td>${detail}</td></tr>`}).join('');return heading('ACCOUNTABILITY','Audit history','See who changed a record, when it changed and the exact values before and after.')+`<div class="kpis">${kpi('Recent actions',logs.length,'Latest 120 entries shown','◷')}${kpi('Edits with change details',edited.length,'Tracked since the audit upgrade','✓')}${kpi('Staff accounts involved',new Set(logs.map(a=>a.actor_id).filter(Boolean)).size,'Within the displayed history','▦')}${kpi('Record types',new Set(logs.map(a=>a.entity_type)).size,'Within the displayed history','▤')}</div>`+panel('Activity trail','Older entries remain stored. Earlier edits may have action details without before-and-after values.',`<div class="toolbar"><input id="audit-search" class="search-input" placeholder="Search staff, record or action…" aria-label="Search audit history"></div>`+listTable(['When','Staff member','Action','Record / reference','Change details'],rows,'Changes appear here after records are saved.'))}
function bindPage(){$('#audit-search')?.addEventListener('input',e=>{const q=e.target.value.toLowerCase();document.querySelectorAll('[data-audit-search]').forEach(r=>r.hidden=!r.dataset.auditSearch.includes(q))});document.querySelectorAll('#content [data-page]').forEach(x=>x.addEventListener('click',e=>{e.preventDefault();go(x.dataset.page)}));document.querySelectorAll('[data-action]').forEach(x=>x.addEventListener('click',()=>action(x.dataset.action)));$('#inventory-search')?.addEventListener('input',filterInventory);$('#inventory-filter')?.addEventListener('change',filterInventory);document.querySelectorAll('[data-event]').forEach(x=>x.addEventListener('click',()=>openEvent(x.dataset.event)));document.querySelectorAll('[data-payment]').forEach(x=>x.addEventListener('click',()=>openPayment(x.dataset.payment)));document.querySelectorAll('[data-void-sale]').forEach(x=>x.addEventListener('click',()=>confirmAction('void_sale',{id:x.dataset.voidSale},'Void this sale and return its stock to inventory?')));document.querySelectorAll('[data-void-expense]').forEach(x=>x.addEventListener('click',()=>confirmAction('void_expense',{id:x.dataset.voidExpense},'Void this expense? It will remain in the audit history.')));document.querySelectorAll('[data-edit-expense]').forEach(x=>x.addEventListener('click',()=>openExpense(x.dataset.editExpense)));document.querySelectorAll('[data-edit-user]').forEach(x=>x.addEventListener('click',()=>openUser(x.dataset.editUser)));document.querySelectorAll('[data-weight]').forEach(x=>x.addEventListener('click',()=>openWeight(x.dataset.weight)));document.querySelectorAll('[data-stock]').forEach(x=>x.addEventListener('click',()=>openStock(x.dataset.stock)));$('#run-report')?.addEventListener('click',loadReport);$('#csv-export')?.addEventListener('click',exportCSV);$('#print-report')?.addEventListener('click',()=>window.print());$('#modal-form')?.addEventListener('submit',saveModal);document.querySelectorAll('[data-close="1"]').forEach(x=>x.addEventListener('click',closeModal))}
function filterInventory(){const q=($('#inventory-search')?.value||'').toLowerCase(),f=$('#inventory-filter')?.value||'all';document.querySelectorAll('#content tr[data-search]').forEach(r=>{const hitq=r.dataset.search.includes(q);let hit=f==='all'||r.dataset.kind===f||r.dataset.division===f||(f==='ingredients'&&r.dataset.kind==='ingredient')||(f==='low'&&r.dataset.low==='true');r.style.display=hitq&&hit?'':'none'})}
function action(a){if(a==='new'){if(page==='dashboard'||page==='production')return openBatch(user.role==='division_staff'?user.division:'poultry');if(page==='sales')return openSale();if(page==='expenses')return openExpense();if(page==='users')return openUser();if(page==='inventory'){const i=state.items[0];return i?openStock(i.id):toast('No inventory items available.',true);}if(page==='cattle'||page==='hatchery'||page==='eggs'||page==='feedmill')return openCreateHatchOrAnimal();return openBatch(page)}if(a==='new-sale')return openSale();if(a==='new-egg')return openEgg();if(a==='new-feed')return openFeed()}
function showModal(title,eyebrow,fields,submitLabel='Save record'){ $('#modal-title').textContent=title;$('#modal-eyebrow').textContent=eyebrow;$('#modal-fields').innerHTML=fields;$('#modal-submit').innerHTML=submitLabel+' <span>→</span>';$('#modal-form').dataset.action='';$('#modal-form').dataset.id='';$('#modal-form').reset();$('#modal').classList.remove('hidden');setTimeout(()=>$('#modal-fields input, #modal-fields select')?.focus(),50)}function closeModal(){$('#modal').classList.add('hidden')}
function field(name,label,type='text',opts={}){const span=opts.span?' span-2':'';const req=opts.required===false?'':' required';let input;if(type==='select'){input=`<select name="${name}"${req}>${(opts.options||[]).map(([v,t])=>`<option value="${esc(v)}">${esc(t)}</option>`).join('')}</select>`}else if(type==='textarea'){input=`<textarea name="${name}" placeholder="${esc(opts.placeholder||'')}"${req?' required':''}></textarea>`}else input=`<input name="${name}" type="${type}" ${type==='number'?`min="${opts.min??0}" step="${opts.step||'any'}"`:''} placeholder="${esc(opts.placeholder||'')}" value="${esc(opts.value||'')}"${req}>`;return `<label class="field${span}">${label}${input}</label>`}
function divisionOptions(){return (state.divisions||[]).filter(d=>user.role!=='division_staff'||d.slug===user.division).map(d=>[d.slug,d.name])}
function openBatch(div){if(!DIVS.some(d=>d[0]===div))div=user.role==='division_staff'?user.division:'poultry';const name=DIVS.find(d=>d[0]===div)?.[1]||'Farm';const units={poultry:'birds',piggery:'pigs',fishery:'fish',eggs:'eggs',hatchery:'eggs',cattle:'head',feedmill:'kg'};let fields=field('division','Farm division','select',{options:divisionOptions()})+field('code','Batch or group code','text',{placeholder:'e.g. POUL-001'})+field('subtype','Breed / type','text',{required:false,placeholder:'e.g. Noiler / catfish'})+field('date','Start date','date',{value:today()})+field('quantity','Opening quantity','number',{min:'0.01',step:'0.01'})+field('unit','Quantity unit','select',{options:[[units[div]||'head',units[div]||'head'],['kg','kg'],['birds','birds'],['pigs','pigs'],['fish','fish'],['eggs','eggs'],['head','head'],['bags','bags'] ]})+field('product_name','Inventory product label','text',{required:false,placeholder:name+' production'})+field('reorder_level','Low-stock threshold','number',{required:false,min:'0',step:'0.01',value:'0'})+field('notes','Notes','textarea',{required:false,span:true});showModal('Add a production batch',name.toUpperCase(),fields);$('#modal-fields [name=division]').value=div;$('#modal-form').dataset.action='create_record'}
function openEvent(id){const b=state.batches.find(x=>x.id===id);if(!b)return;let types=b.division_slug==='poultry'?[['addition','Addition'],['mortality','Mortality'],['sale','Birds sold'],['transfer_in','Transfer in'],['transfer_out','Transfer out']]:b.division_slug==='piggery'?[['birth','Births'],['death','Deaths'],['sale','Sold'],['transfer_in','Transfer in'],['transfer_out','Transfer out']]:[['addition','Stock addition'],['death','Deaths'],['harvest','Harvest'],['sale','Sold'],['transfer_in','Transfer in'],['transfer_out','Transfer out']];showModal('Record a movement',b.code,field('event_type','Movement type','select',{options:types})+field('quantity','Quantity','number',{min:'0.01',step:'0.01'})+field('date','Effective date','date',{value:today()})+field('notes','Note','textarea',{required:false,span:true}));$('#modal-form').dataset.action='event';$('#modal-form').dataset.batchId=id}
function openEgg(){const batches=state.batches.filter(b=>b.division_slug==='eggs').map(b=>[b.id,b.code]);showModal('Record egg collection','EGG PRODUCTION',field('date','Collection date','date',{value:today()})+field('batch_id','Layer flock (optional)','select',{required:false,options:[['','Choose a flock'],...batches]})+field('good','Good eggs','number',{min:'0',step:'1'})+field('damaged','Damaged eggs','number',{min:'0',step:'1',required:false,value:'0'})+field('notes','Note','textarea',{required:false,span:true}));$('#modal-form').dataset.action='save_egg'}
function openHatch(){showModal('Create a hatch batch','HATCHERY',field('code','Hatch batch code','text',{placeholder:'HAT-001'})+field('set_date','Set date','date',{value:today()})+field('eggs_set','Eggs set','number',{min:'1',step:'1'})+field('chicks_hatched','Chicks hatched','number',{min:'0',step:'1',required:false,value:'0'})+field('rejected_eggs','Rejected eggs','number',{min:'0',step:'1',required:false,value:'0'})+field('hatch_date','Hatch date','date',{required:false})+field('notes','Notes','textarea',{required:false,span:true}));$('#modal-form').dataset.action='save_hatchery'}
function openAnimal(){showModal('Register an animal','CATTLE',field('tag','Animal tag','text',{placeholder:'COW-001'})+field('breed','Breed','text',{placeholder:'e.g. White Fulani'})+field('sex','Sex','select',{options:[['Unknown','Unknown'],['Female','Female'],['Male','Male']]})+field('date','Date entered','date',{value:today()})+field('weight','Starting weight (kg)','number',{required:false,min:'0.01',step:'0.1'})+field('notes','Notes','textarea',{required:false,span:true}));$('#modal-form').dataset.action='save_animal'}
function openWeight(id){const a=state.animals.find(x=>x.id===id);showModal('Record weight','CATTLE · '+a.tag,field('weight','Weight in kg','number',{min:'0.1',step:'0.1'})+field('date','Measured on','date',{value:today()})+field('notes','Note','textarea',{required:false,span:true}));$('#modal-form').dataset.action='animal_weight';$('#modal-form').dataset.animalId=id}
function openFeed(){const items=state.items.filter(i=>['ingredient','finished_feed'].includes(i.item_type));const outputs=items.filter(i=>i.item_type==='finished_feed');const ingredients=items.filter(i=>i.item_type==='ingredient');if(!outputs.length||!ingredients.length)return toast('Add ingredient and finished-feed items to inventory first.',true);showModal('Produce a feed batch','FEEDMILL',field('code','Production batch','text',{placeholder:'FEED-001'})+field('date','Production date','date',{value:today()})+field('output_item_id','Feed type','select',{options:outputs.map(i=>[i.id,`${i.product_name} · ${fmt(i.balance)} ${i.unit} available`])})+field('output_kg','Finished feed output (kg)','number',{min:'0.01',step:'0.01'})+field('maize','Yellow maize (kg)','number',{required:false,min:'0',step:'0.01',value:'0'})+field('soya','Soybean meal (kg)','number',{required:false,min:'0',step:'0.01',value:'0'})+field('bran','Wheat bran (kg)','number',{required:false,min:'0',step:'0.01',value:'0'})+field('notes','Notes','textarea',{required:false,span:true}));$('#modal-form').dataset.action='produce_feed'}
function openSale(){if(user.role==='storekeeper')return toast('Your role cannot record sales.',true);const available=state.items.filter(i=>num(i.balance)>0);const products=available.map(i=>[i.id,`${i.product_name} · ${fmt(i.balance)} ${i.unit} available`]);if(!products.length)return toast('Add saleable items to inventory before recording a sale.',true);const divopts=divisionOptions();showModal('Record a sale','SALES & PAYMENTS',field('sale_no','Sale reference','text',{required:false,placeholder:'Generated if blank'})+field('date','Sale date','date',{value:today()})+field('division','Farm division','select',{options:divopts})+field('customer','Customer','text',{required:false,value:'Walk-in customer'})+field('item_id','Sale product','select',{options:products})+field('quantity','Quantity','number',{min:'0.01',step:'0.01'})+field('unit_price','Price per unit (NGN)','number',{min:'0',step:'0.01'})+field('paid','Amount paid (NGN)','number',{required:false,min:'0',step:'0.01',value:'0'}));$('#modal-form').dataset.action='save_sale'}
function openPayment(id){const s=state.sales.find(x=>x.id===id);const balance=num(s.total_amount)-num(s.paid_amount);showModal('Record a payment','SALE · '+s.sale_no,field('amount','Payment received (NGN)','number',{min:'0.01',max:balance,step:'0.01',placeholder:`Balance ${money(balance)}`}));$('#modal-form').dataset.action='sale_payment';$('#modal-form').dataset.id=id}
function openExpense(id){const e=state.expenses.find(x=>x.id===id);showModal(e?'Edit expense':'Record an expense','EXPENSES',field('division','Division','select',{options:divisionOptions()})+field('category','Category','select',{options:['Feed','Veterinary','Transport','Utilities','Labour','Repairs','Supplies','Other'].map(x=>[x,x])})+field('amount','Amount (NGN)','number',{min:'0.01',step:'0.01'})+field('date','Date','date',{value:today()})+field('description','Description','textarea',{span:true}));$('#modal-form').dataset.action='save_expense';if(e){$('#modal-form').dataset.id=id;Object.entries({division:e.division_slug,category:e.category,amount:e.amount,date:e.expense_date,description:e.description}).forEach(([k,v])=>$('#modal-fields [name='+k+']').value=v)}}
function openUser(id){const u=state.users.find(x=>x.id===id);showModal(u?'Edit staff access':'Create a staff account','ADMINISTRATION',field('full_name','Full name','text')+field('email','Email','email',{required:!u})+field('role','Role','select',{options:Object.entries(ROLE).map(([v,t])=>[v,t])})+field('division_slug','Assigned division','select',{required:false,options:[['','All divisions'],...divisionOptions()]})+field('password',u?'New password (optional)':'Temporary password','password',{required:!u,placeholder:'At least 10 characters'})+(u?field('active','Access','select',{options:[['true','Active'],['false','Disabled']]}):''));$('#modal-form').dataset.action='save_user';if(u){$('#modal-form').dataset.id=id;Object.entries({full_name:u.full_name,email:u.email,role:u.role,division_slug:u.division_slug||'',active:String(u.active)}).forEach(([k,v])=>{$('#modal-fields [name='+k+']').value=v})}}
function openStock(id){const i=state.items.find(x=>x.id===id);showModal('Adjust stock','INVENTORY · '+i.product_name,field('movement','Movement','select',{options:[['inventory_receive','Receive stock'],['inventory_issue','Issue stock']]})+field('quantity',`Quantity (${i.unit})`,'number',{min:'0.01',step:'0.01'})+field('date','Effective date','date',{value:today()}));$('#modal-form').dataset.action='stock';$('#modal-form').dataset.itemId=id}
function actionClick(a){if(a==='new')return openBatch(user.role==='division_staff'?user.division:'poultry');if(a==='new-sale')return openSale();if(a==='new-egg')return openEgg();if(a==='new-feed')return openFeed()}
async function saveModal(e){e.preventDefault();const form=e.currentTarget,fd=new FormData(form),a=form.dataset.action,p=Object.fromEntries(fd.entries());p.id=form.dataset.id||undefined;let action=a;try{if(a==='event'){p.batch_id=form.dataset.batchId;action='event'}if(a==='animal_weight'){p.animal_id=form.dataset.animalId;action='animal_weight'}if(a==='stock'){action=p.movement; p.item_id=form.dataset.itemId;delete p.movement}if(a==='produce_feed'){p.inputs=[];for(const [sku,name] of [['ING-MAIZE','maize'],['ING-SOYA','soya'],['ING-BRAN','bran']]){const q=num(p[name]);const item=state.items.find(i=>i.sku===sku);if(q>0&&item)p.inputs.push({item_id:item.id,quantity_kg:q})}if(!p.inputs.length)throw Error('Enter the amount of at least one ingredient.');delete p.maize;delete p.soya;delete p.bran}if(a==='save_sale'){p.lines=[{item_id:p.item_id,quantity:p.quantity,unit_price:p.unit_price}];delete p.item_id;delete p.quantity;delete p.unit_price}await api(action,p);closeModal();await refresh();toast('Record saved successfully.')}catch(err){toast(err.message,true)}}
function confirmAction(action,payload,prompt){if(!confirm(prompt))return;api(action,payload).then(()=>refresh()).then(()=>toast('Transaction updated.')).catch(e=>toast(e.message,true))}
function openCreateHatchOrAnimal(){if(page==='cattle')return openAnimal();if(page==='hatchery')return openHatch();if(page==='eggs')return openEgg();if(page==='feedmill')return openFeed()}
let reportRequestId=0;
async function loadReport(){const requestId=++reportRequestId;try{const filters={from:$('#report-from').value,to:$('#report-to').value,division:$('#report-division').value};if(!filters.from||!filters.to)throw Error('Choose both a start and end date.');if(filters.from>filters.to)throw Error('The start date must be on or before the end date.');const data=await api('report',filters);if(requestId!==reportRequestId||page!=='reports')return;renderReport(data,filters)}catch(e){if(requestId===reportRequestId)toast(e.message,true)}}
async function exportCSV(){try{const data=await api('csv');const sections=[['SALES',data.sales||[]],['EXPENSES',data.expenses||[]],['INVENTORY MOVEMENTS',data.movements||[]]],lines=[];for(const [title,rows] of sections){lines.push(title);if(rows.length){const keys=Object.keys(rows[0]);lines.push(keys.map(csvCell).join(','));for(const r of rows)lines.push(keys.map(k=>csvCell(r[k])).join(','))}else lines.push('No records');lines.push('')}const blob=new Blob(['\ufeff'+lines.join('\r\n')],{type:'text/csv;charset=utf-8'}),a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download=`fol-hope-report-${today()}.csv`;a.click();URL.revokeObjectURL(a.href)}catch(e){toast(e.message,true)}}
function csvCell(v){let s=typeof v==='object'&&v!==null?JSON.stringify(v):String(v??'');return '"'+s.replaceAll('"','""')+'"'}
api('state').then(openApp).catch(e=>{if(!/session expired/i.test(e.message))$('#login-error').textContent=e.message;});
